# 标准 Tool 定义
tool_definition = {
 "name": "search_database", # 工具唯一标识
 "description": "搜索公司产品数据库，支持按名称、类别、价格范围查询。"
 "当用户询问产品信息、库存、价格时使用此工具。", # 关键！描述要清晰
 "parameters": { # JSON Schema 格式的参数定义
 "type": "object",
 "properties": {
 "query": {
 "type": "string",
 "description": "搜索关键词"
 },
 "category": {
 "type": "string",
 "enum": ["electronics", "clothing", "food"],
 "description": "产品类别筛选"
 },
 "max_results": {
 "type": "integer",
 "default": 10,
 "description": "最多返回结果数"
 }
 },
 "required": ["query"]
 }
}
核对参数、返回/状态与外部副作用；原文没有给出的行为需用测试验证。
